using System;using System.IO;using System.Linq;using System.Collections.Generic;using V15Voice;
public static class ReportAudioCompatibilityTests {
 sealed class Engine:KokoroEngine {public override void CheckFiles(){}public override Wave Generate(string text,double speed,string output){int n=(int)Math.Round((.9+text.Length*.025)/speed*24000);return new Wave{Rate=24000,Samples=Enumerable.Range(0,n).Select(i=>i<n-1000?(short)(4000*Math.Sin(i*.067)):(short)0).ToArray()};}}
 public static void Main(){string root=Path.Combine(Path.GetTempPath(),"v15-report-byte-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"breaths"));new Wave{Rate=24000,Samples=Enumerable.Range(0,4800).Select(i=>(short)(1000*Math.Sin(i*.071))).ToArray()}.Write(Path.Combine(root,"breaths","test.wav"));
 foreach(string mode in new[]{"locked","txt","anchored"}){var cues=Enumerable.Range(1,4).Select(i=>new Cue{Id=i,Start=(i-1)*3.45,End=i*3.45,Text="Hello, this sentence ends here."}).ToList();if(mode=="txt")cues=LongText.Parse("Hello, this is a natural paragraph. Another sentence ends this paragraph.");var o=new RenderOptions{Locked=mode=="locked",Prose=mode=="txt",Anchored=mode=="anchored",Punctuation=PunctuationMode.Custom,Breathing=BreathMode.Auto,BaseSpeed=1,MinSpeed=.5,MaxSpeed=1.6,SlowShort=true,Gap=.1,NormalizeLoudness=true,ReportContext=new VoiceReportContext{SourceCues=VoiceRenderReport.Snapshot(cues)}};using(var e=new Engine{Root=root}){string output=Renderer.Render(cues,e,o,Path.Combine(root,mode+".wav"),(p,m)=>{});Console.WriteLine(mode+" "+StateFiles.Hash(output));}}
 }
}
